\documentclass[11pt]{article}

\usepackage{amsmath,amssymb,amsthm}
\usepackage[margin=1in]{geometry}
\usepackage{hyperref}

\newtheorem{theorem}{Theorem}
\newtheorem{proposition}[theorem]{Proposition}
\newtheorem{lemma}[theorem]{Lemma}
\newtheorem{corollary}[theorem]{Corollary}
\theoremstyle{definition}
\newtheorem{definition}[theorem]{Definition}

\newcommand{\dom}{\operatorname{dom}}
\newcommand{\bbox}{\Box}
\newcommand{\ddia}{\Diamond}
\newcommand{\true}{\mathrm{true}}
\newcommand{\false}{\mathrm{false}}

\title{The Modal Logic of Forcing is S4.2:\\
A Combinatorial Separation via the Domination Order}
\author{Aristotle}
\date{2026-07-14}

\begin{document}
\maketitle

\begin{abstract}
The modal logic of forcing interprets the possibility operator $\ddia$ as
``forceable'' and the necessity operator $\bbox$ as ``true in every forcing
extension.'' A landmark theorem of Hamkins and L\"owe identifies this logic as
\textbf{S4.2}, the normal modal logic axiomatized by reflexivity (T),
transitivity (4), and confluence/directedness (.2). A recurring subtlety is
that S4.2 must be \emph{separated} from the stronger, more familiar system S5:
forcing is asymmetric---one may pass to a generic extension but cannot in
general force back to the ground model---and this asymmetry is precisely what
prevents the collapse to S5. We give a self-contained, fully combinatorial
account of this separation. We work in an abstract Kripke semantics, proving
the correspondence between each modal axiom and its defining frame condition,
including the exact biconditional between Axiom .2 and confluence. We then
construct a concrete \textbf{asymmetric forcing frame} whose worlds are truth
assignments and whose accessibility relation is the pointwise
\textbf{domination order} $\dom\,w\,v :\Leftrightarrow \forall a,\ w(a)=\true
\Rightarrow v(a)=\true$ (``an extension may switch atoms on, never off''). We
prove that this frame is reflexive, transitive, and confluent---so it validates
all of S4.2---yet is not Euclidean and genuinely \textbf{refutes Axiom 5}, via
an explicit two-atom counterexample. This yields a clean semantic separation of
S4.2 from S5, isolating the exact combinatorial reason the modal logic of
forcing is S4.2.
\end{abstract}

\noindent\textbf{Keywords:} modal logic of forcing, S4.2, S5, Kripke
semantics, confluence, domination order, set-theoretic multiverse,
independence, Continuum Hypothesis.

\section{Introduction}

\subsection{Forcing, independence, and the multiverse}
Cohen's method of \emph{forcing} revolutionized set theory by producing, from
any model of the standard axioms, a richer \emph{generic extension} in which a
prescribed statement holds. It is the engine behind the celebrated independence
results: the Continuum Hypothesis (CH), the Axiom of Choice over the base
theory, Suslin's Hypothesis, and countless others can be forced true or false
at will. Rather than viewing independence as a deficiency, the
\emph{multiverse} conception of set theory takes the plurality of models as the
fundamental object of study: there is no single absolute universe of sets, but
a vast landscape of universes connected by the forcing relation.

Once universes are connected by a travel relation, one may ask about the
\emph{logic of travel}. Reading $\ddia P$ as ``$P$ is forceable'' and $\bbox P$
as ``$P$ holds in all forcing extensions,'' the natural question is: which
valid modal principles govern these operators, uniformly across all models?
Hamkins and L\"owe answered this: the \emph{provably valid} principles of
forcing are exactly the theorems of the modal logic \textbf{S4.2}.

\subsection{The role of asymmetry, and the goal of this paper}
S4.2 is strictly weaker than S5. The two differ by a single axiom: S5
additionally validates Axiom 5, $\ddia P \to \bbox\ddia P$. It is therefore
essential---both conceptually and technically---to demonstrate that the modal
logic of forcing is \emph{genuinely} S4.2 and does \textbf{not} collapse to S5.
The conceptual reason is the \textbf{asymmetry of forcing}: a generic extension
adds objects irreversibly, and one cannot in general force from an extension
back down to its ground model. Symmetric models of the multiverse miss this
entirely and spuriously validate S5.

This paper isolates the separation in its purest combinatorial form. We
(1) develop an abstract Kripke layer in which each axiom $K,T,4,.2,5$ is derived
from---and, for .2, shown equivalent to---its frame condition
(Section~\ref{sec:corr}); (2) construct the \textbf{domination frame}, an
explicitly asymmetric forcing model, and prove it validates S4.2
(Section~\ref{sec:frame}); and (3) prove that the same frame refutes Axiom 5,
via an explicit two-atom witness, yielding the semantic separation
(Section~\ref{sec:sep}). Everything is elementary and self-contained.

\section{Preliminaries: Kripke frames and modal operators}

A \textbf{Kripke frame} is a pair $(W,R)$ where $W$ is a nonempty set of
\emph{worlds} and $R \subseteq W \times W$ is an \emph{accessibility relation};
we write $R\,w\,v$ for ``$v$ is accessible from $w$.'' A \textbf{predicate} is a
map $P : W \to \{\true,\false\}$, identified with the set of worlds at which it
holds.

\begin{definition}[Modal operators]
Given $(W,R)$, define
\[
(\bbox P)(w) :\Longleftrightarrow \forall v,\ R\,w\,v \Rightarrow P(v),
\qquad
(\ddia P)(w) :\Longleftrightarrow \exists v,\ R\,w\,v \wedge P(v).
\]
\end{definition}

A frame \textbf{validates} a schema if it holds at every world for every
predicate. The relevant frame conditions are: \emph{reflexive}
($R\,w\,w$); \emph{transitive} ($R\,w\,v \wedge R\,v\,u \Rightarrow R\,w\,u$);
\emph{confluent/directed} ($R\,x\,y \wedge R\,x\,z \Rightarrow \exists u,\
R\,y\,u \wedge R\,z\,u$); \emph{Euclidean} ($R\,x\,y \wedge R\,x\,z \Rightarrow
R\,y\,z$). The systems are $\mathrm{S4} = K+T+4$; $\mathrm{S4.2} =
\mathrm{S4}+.2$; $\mathrm{S5} = \mathrm{S4}+5$. Over reflexive-transitive
frames, Euclidean implies confluent, so S5 is strictly stronger than S4.2.

\section{The abstract correspondence layer}\label{sec:corr}
Fix a frame $(W,R)$, a world $w$, and predicates $P,Q$.

\begin{proposition}[Duality, distribution, necessitation]
$\ddia P \leftrightarrow \neg\bbox\neg P$ and $\bbox P \leftrightarrow
\neg\ddia\neg P$. If $P(v)\to Q(v)$ for all $v$ then $\bbox P(w)\to\bbox Q(w)$
and $\ddia P(w)\to\ddia Q(w)$. If $P(v)$ for all $v$ then $\bbox P(w)$
(necessitation). Axiom K holds: $\bbox(P\to Q)(w)\to\bbox P(w)\to\bbox Q(w)$.
\end{proposition}
\begin{proof}
All are immediate from the definitions: duality is the De Morgan interchange of
$\forall/\exists$; monotonicity, necessitation, and K follow by applying the
hypothesis pointwise at each accessible world.
\end{proof}

\begin{theorem}[T from reflexivity]
If $R$ is reflexive, then $\bbox P(w)\to P(w)$.
\end{theorem}
\begin{proof}
Instantiate $\bbox P(w)=\forall v(R\,w\,v\to P(v))$ at $v=w$, using $R\,w\,w$.
\end{proof}

\begin{theorem}[4 from transitivity]
If $R$ is transitive, then $\bbox P(w)\to\bbox\bbox P(w)$.
\end{theorem}
\begin{proof}
Assume $\bbox P(w)$. Fix $v$ with $R\,w\,v$ and $u$ with $R\,v\,u$; by
transitivity $R\,w\,u$, so $P(u)$. Hence $\bbox P(v)$ for all accessible $v$,
i.e. $\bbox\bbox P(w)$.
\end{proof}

\begin{theorem}[.2 soundness from confluence]
If $R$ is confluent, then $\ddia\bbox P(w)\to\bbox\ddia P(w)$.
\end{theorem}
\begin{proof}
Assume $\ddia\bbox P(w)$: there is $v$ with $R\,w\,v$ and $\bbox P(v)$. Fix any
$u$ with $R\,w\,u$. By confluence on $R\,w\,v$ and $R\,w\,u$ there is $t$ with
$R\,v\,t$ and $R\,u\,t$. From $\bbox P(v)$ and $R\,v\,t$ we get $P(t)$; and
$R\,u\,t$ witnesses $\ddia P(u)$. As $u$ was arbitrary, $\bbox\ddia P(w)$.
\end{proof}

\begin{theorem}[.2 characterizes confluence]
If $(W,R)$ validates $\ddia\bbox P \to \bbox\ddia P$ for every predicate $P$
and every world, then $R$ is confluent.
\end{theorem}
\begin{proof}
Fix $x,y,z$ with $R\,x\,y$ and $R\,x\,z$. Take $P(t):\Leftrightarrow R\,y\,t$.
At $x$ we have $\ddia\bbox P$: travel to $y$, where $\bbox P$ holds because
every $t$ with $R\,y\,t$ satisfies $P(t)$ by definition. By the assumed schema
$\bbox\ddia P(x)$ holds; instantiating at $z$ gives $\ddia P(z)$: some $u$ with
$R\,z\,u$ and $R\,y\,u$. Then $u$ is a common successor of $y$ and $z$.
\end{proof}

\begin{theorem}[5 from the Euclidean property]
If $R$ is Euclidean, then $\ddia P(w)\to\bbox\ddia P(w)$.
\end{theorem}
\begin{proof}
Assume $\ddia P(w)$: there is $v$ with $R\,w\,v$ and $P(v)$. Fix $u$ with
$R\,w\,u$. By the Euclidean property on $R\,w\,u$ and $R\,w\,v$ we get
$R\,u\,v$, so $\ddia P(u)$ is witnessed by $v$. Hence $\bbox\ddia P(w)$.
\end{proof}

\section{The asymmetric forcing frame}\label{sec:frame}

\begin{definition}[Worlds and the domination order]
Fix a type $\alpha$ of \emph{atoms}. A \textbf{world} is a truth assignment
$w:\alpha\to\{\true,\false\}$, with $w(a)=\true$ meaning ``atom $a$ holds in
$w$.'' The accessibility relation is the pointwise \textbf{domination order}
\[
\dom\,w\,v :\Longleftrightarrow \forall a,\ w(a)=\true \Rightarrow v(a)=\true.
\]
Thus $v$ decides at least as many atoms positively as $w$: passing to $v$ may
switch atoms \emph{on} but never \emph{off}.
\end{definition}

\begin{proposition}[Reflexivity]
$\dom$ is reflexive.
\end{proposition}
\begin{proof}
$w(a)=\true\Rightarrow w(a)=\true$.
\end{proof}

\begin{proposition}[Transitivity]
$\dom$ is transitive.
\end{proposition}
\begin{proof}
If $\dom\,x\,y$, $\dom\,y\,z$, and $x(a)=\true$, then $y(a)=\true$, hence
$z(a)=\true$.
\end{proof}

\begin{proposition}[Confluence]\label{prop:conf}
$\dom$ is confluent. For any worlds $y,z$ their \emph{join} $j(a):=y(a)\vee
z(a)$ satisfies $\dom\,y\,j$ and $\dom\,z\,j$.
\end{proposition}
\begin{proof}
If $y(a)=\true$ then $y(a)\vee z(a)=\true$, so $\dom\,y\,j$; symmetrically
$\dom\,z\,j$. (The hypotheses $\dom\,x\,y,\dom\,x\,z$ are not even required.)
\end{proof}

The join is the combinatorial shadow of amalgamating two forcing extensions.

\begin{theorem}[S4.2 soundness of the domination frame]
For every predicate $P$ and world $w$, the domination frame validates
\textup{T} ($\bbox P(w)\to P(w)$), \textup{4} ($\bbox P(w)\to\bbox\bbox P(w)$),
and \textup{.2} ($\ddia\bbox P(w)\to\bbox\ddia P(w)$). Hence it is a model of
S4.2.
\end{theorem}
\begin{proof}
Apply the correspondence theorems of Section~\ref{sec:corr} to the reflexivity,
transitivity, and confluence just established.
\end{proof}

\section{Separation: the frame refutes S5}\label{sec:sep}

Take $\alpha=\{\text{``true''},\text{``false''}\}$ (i.e. $\alpha=\mathsf{Bool}$),
and set
\[
\bot(a):=\false,\qquad \top(a):=\true,\qquad m(a):=a.
\]

\begin{lemma}\label{lem:bot}
$\dom\,\bot\,m$ and $\dom\,\bot\,\top$.
\end{lemma}
\begin{proof}
$\bot$ has no positive atoms, so the domination condition is vacuous.
\end{proof}

\begin{lemma}\label{lem:top}
$\neg\,\dom\,\top\,m$.
\end{lemma}
\begin{proof}
The atom ``false'' is on in $\top$ but off in $m$; domination would require it
to remain on.
\end{proof}

\begin{corollary}
$\dom$ is not Euclidean: $\dom\,\bot\,\top$ and $\dom\,\bot\,m$ hold but
$\dom\,\top\,m$ fails.
\end{corollary}

\begin{theorem}[Separation]
There exist a predicate $P$ and a world $w$ with $\ddia P(w)$ true and
$\bbox\ddia P(w)$ false. Consequently the domination frame refutes Axiom 5
while validating all of S4.2, so it is a model of S4.2 that is not a model of
S5.
\end{theorem}
\begin{proof}
Let $w:=\bot$ and $P(t):\Leftrightarrow(t=m)$. By Lemma~\ref{lem:bot},
$\ddia P(\bot)$ holds, witnessed by $m$. Suppose $\bbox\ddia P(\bot)$ held.
Since $\dom\,\bot\,\top$, it would give $\ddia P(\top)$: some $t$ with
$\dom\,\top\,t$ and $t=m$, i.e. $\dom\,\top\,m$, contradicting
Lemma~\ref{lem:top}. Hence $\bbox\ddia P(\bot)$ fails, refuting the schema
$\ddia P\to\bbox\ddia P$.
\end{proof}

Intuitively: from the information-poor $\bot$, being in world $m$ is
\emph{possible}; but one can also travel to $\top$, from which $m$ is
unreachable (reaching it would require switching the atom ``false'' back off).
Possibility is \emph{lost} by extending to $\top$---the modal fingerprint of
the fact that forcing cannot run backward.

\section{Discussion}

\paragraph{Why S4.2 and not S5.}
The separation pinpoints the structural feature responsible: directional
monotonicity. The domination order builds reflexivity, transitivity, and
confluence---hence all of S4.2---from one rule, ``on stays on,'' while
withholding symmetry; the explicit $\bot/\top/m$ witness shows Axiom 5 truly
fails. A symmetric model would validate 5 and collapse to S5, hiding the
phenomenon.

\paragraph{Exact correspondence for .2.}
The biconditional between Axiom .2 and confluence shows the characteristic
forcing axiom \emph{characterizes} confluence, giving an exact match between the
syntactic axiom and the amalgamability of extensions.

\paragraph{Buttons and switches.}
\emph{Buttons} (statements $b$ with $\ddia\bbox b$: once true, forever true)
are exactly the monotone predicates for domination; \emph{switches}
($\bbox\ddia s\wedge\bbox\ddia\neg s$) toggle indefinitely. The asymmetric
frame is the natural home for this theory.

\section{Algorithms}
On a finite atom set the content is directly computable.
\emph{(A) Domination test:} check $w(a)\Rightarrow v(a)$ for each $a$, $O(|A|)$.
\emph{(B) Join / confluence witness:} return $j(a)=y(a)\vee z(a)$, which
dominates both, $O(|A|)$.
\emph{(C) Modal evaluation:} enumerate $2^{|A|}$ worlds and compute
$\bbox P(w)=\bigwedge_{\dom\,w\,v}P(v)$, $\ddia P(w)=\bigvee_{\dom\,w\,v}P(v)$.
\emph{(D) Axiom checker:} evaluate both sides of a schema at every world over a
sample of predicates and report validity or a refuting witness.

\section{Applications}
Foundations of set theory (an orderly logic for the independence phenomenon);
provability and interpretability logics (a reusable S4.2-vs-S5 template);
knowledge representation (monotonic information states with T/4/.2 but not 5);
and concurrency/rewriting (the .2$\leftrightarrow$confluence link to the
Church--Rosser property).

\section{Future Directions}
\begin{enumerate}
\item \textbf{Completeness for S4.2.} Prove a formula is valid in every
reflexive-transitive-confluent frame iff it is a theorem of S4.2 (Hamkins--L\"owe),
via a syntactic proof system and a canonical-model/filtration argument.
\item \textbf{Sentence-level modal operators.} Extend a syntactic sentence
datatype with $\bbox,\ddia$ and define evaluation over the forcing frame.
\item \textbf{Buttons and switches.} Formalize switches and buttons and prove
the independent-buttons-and-switches control theorem; the asymmetric frame is
the right setting since buttons are the monotone predicates for domination.
\item \textbf{Boolean-valued models.} Replace two-valued worlds by assignments
into a complete Boolean algebra, recovering the classical forcing construction.
\end{enumerate}

\section{Conclusion}
We gave a self-contained combinatorial separation of S4.2 from S5 via the
asymmetric domination order on truth assignments. The frame validates T, 4, and
the characteristic axiom .2---proved sound from, and for .2 equivalent to,
their frame conditions---while an explicit two-atom witness refutes Axiom 5. The
single rule ``an extension switches atoms on, never off'' simultaneously
supplies everything S4.2 demands and denies the symmetry S5 requires. This is
the precise combinatorial reason the modal logic of forcing is S4.2: forcing
adds, but never subtracts.

\end{document}

