from __future__ import annotations
from itertools import product

World = tuple[bool, ...]

def all_worlds(n: int) -> list[World]:
    return [tuple(b) for b in product([False, True], repeat=n)]

def dom(w: World, v: World) -> bool:
    return all((not a) or b for a, b in zip(w, v))

def join(y: World, z: World) -> World:
    return tuple(a or b for a, b in zip(y, z))

def is_reflexive(ws: list[World]) -> bool:
    return all(dom(w, w) for w in ws)

def is_transitive(ws: list[World]) -> bool:
    return all((not (dom(x, y) and dom(y, z))) or dom(x, z)
               for x in ws for y in ws for z in ws)

def is_confluent(ws: list[World]) -> bool:
    for x in ws:
        for y in ws:
            for z in ws:
                if dom(x, y) and dom(x, z):
                    u = join(y, z)
                    if not (dom(y, u) and dom(z, u)):
                        return False
    return True

def is_euclidean(ws: list[World]) -> bool:
    return all((not (dom(x, y) and dom(x, z))) or dom(y, z)
               for x in ws for y in ws for z in ws)

if __name__ == "__main__":
    for n in (1, 2, 3):
        ws = all_worlds(n)
        print(f"n={n}: reflexive={is_reflexive(ws)}, transitive={is_transitive(ws)}, "
              f"confluent={is_confluent(ws)}, euclidean={is_euclidean(ws)}")

