from typing import Callable

World = tuple[bool, ...]
Predicate = Callable[[World], bool]

def dom(w: World, v: World) -> bool:
    return all((not a) or b for a, b in zip(w, v))

class Atom:
    def __init__(self, p: Predicate) -> None:
        self.p = p

class Not:
    def __init__(self, f: object) -> None:
        self.f = f

class And:
    def __init__(self, f: object, g: object) -> None:
        self.f, self.g = f, g

class Box:
    def __init__(self, f: object) -> None:
        self.f = f

class Dia:
    def __init__(self, f: object) -> None:
        self.f = f

def evaluate(formula: object, w: World, worlds: list[World]) -> bool:
    if isinstance(formula, Atom):
        return formula.p(w)
    if isinstance(formula, Not):
        return not evaluate(formula.f, w, worlds)
    if isinstance(formula, And):
        return evaluate(formula.f, w, worlds) and evaluate(formula.g, w, worlds)
    if isinstance(formula, Box):
        return all(evaluate(formula.f, v, worlds) for v in worlds if dom(w, v))
    if isinstance(formula, Dia):
        return any(evaluate(formula.f, v, worlds) for v in worlds if dom(w, v))
    raise TypeError(f"unknown formula node: {formula!r}")

