import itertools
import matplotlib.pyplot as plt

def hasse(n: int = 3) -> None:
    worlds = [tuple(b) for b in itertools.product([False, True], repeat=n)]
    levels: dict[int, list] = {}
    for w in worlds:
        levels.setdefault(sum(w), []).append(w)
    pos = {}
    for lvl, ws in levels.items():
        for i, w in enumerate(sorted(ws)):
            pos[w] = (i - (len(ws) - 1) / 2, lvl)
    fig, ax = plt.subplots(figsize=(7, 6))
    for w in worlds:
        for a in range(n):
            if not w[a]:
                v = tuple(x or (j == a) for j, x in enumerate(w))
                (x0, y0), (x1, y1) = pos[w], pos[v]
                ax.plot([x0, x1], [y0, y1], color="0.7", zorder=1)
    for w in worlds:
        x, y = pos[w]
        ax.scatter([x], [y], s=600, color="#4C72B0", zorder=2)
        ax.text(x, y, "".join("1" if b else "0" for b in w),
                color="white", ha="center", va="center", fontsize=9)
    ax.set_title(f"Domination lattice on {n} atoms (upward edges only)")
    ax.axis("off")
    plt.tight_layout()
    plt.savefig("domination_lattice.png", dpi=150)
    print("wrote domination_lattice.png")

